```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();

        String s = sc.next();

        char[][] words = new char[M][];
        for (int i = 0; i < M; i++) {
            words[i] = sc.next().toCharArray();
            Arrays.sort(words[i]);
        }

        long P = sc.nextLong();

        int[] positions = new int[M];
        int count = 0;
        for (int i = 0; i < N && count < M; i++) {
            if (s.charAt(i) == '#') {
                positions[count++] = i;
            }
        }

        final long CAP = 1_000_000_001L;
        long[] ways = new long[M + 1];
        ways[M] = 1;

        for (int i = M - 1; i >= 0; i--) {
            long next = ways[i + 1] * (long) K;
            ways[i] = next > CAP ? CAP : next;
        }

        char[] answer = s.toCharArray();
        long rank = P;

        for (int i = 0; i < M; i++) {
            long suffixWays = ways[i + 1];
            char[] word = words[i];

            int pos = 0;
            while (pos < K) {
                char c = word[pos];
                int start = pos;

                while (pos < K && word[pos] == c) {
                    pos++;
                }

                long multiplicity = pos - start;
                long blockSize = multiplicity * suffixWays;

                if (rank > blockSize) {
                    rank -= blockSize;
                } else {
                    answer[positions[i]] = c;
                    rank = (rank - 1) / multiplicity + 1;
                    break;
                }
            }
        }

        System.out.println(new String(answer));
    }
}
